head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[video > P > loop]<br/>Video 컴포넌트의 동영상을 반복 재생할지 설정합니다.",
    "validation" : [
        "loop 설정 시, 동영상 재생이 끝나면 처음부터 다시 재생합니다.",
        "빈 문자열('') 을 설정해도 동영상 재생을 반복합니다.",
        "Video 컴포넌트는 loop 속성값을 출력 HTML 의 video 태그에 전달하며, 실제 동작은 브라우저의 HTML5 video 처리에 따라 결정됩니다.",
        "속성을 한번이라도 설정하면 속성명이 유지되고, 속성명 정의만으로 해당 기능이 설정됩니다.",
        "따라서, 소스에서 직접 속성명을 제거해야 해당 기능이 해제됩니다."
    ]
}

// video 요소별 재생 시작(play) 실패 사유 기록용
scwin.gPlayError = { "target1" : "", "target2" : "", "target3" : "" };



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 재생 시작 결과 문구 반환 (재생이 시작되지 않은 경우를 반복 실패와 구분)
scwin.fn_getPlayState = function (sId) {
    return (scwin.gPlayError[sId] === "") ? "정상" : "실패(" + scwin.gPlayError[sId] + ")";
};



// 재생 길이(약 2초) 를 넘긴 시점의 반복 재생 여부 확인
scwin.btn_playAndCheck_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");

    [el1, el2, el3].forEach(function (el) {
        scwin.gPlayError[el.id] = "";
        el.currentTime = 0;
        let oPromise = el.play();
        if (oPromise && typeof oPromise.catch === "function") {
            oPromise.catch(function (err) { scwin.gPlayError[el.id] = err.name; });
        }
    });

    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("loop 를 loop 로 설정 - 재생 시작 : " + scwin.fn_getPlayState("target1") + " , 재생 길이(duration) : " + el1.duration.toFixed(1) + " , 재생 길이 경과 후 재생 종료(ended) : " + el1.ended);
        wf_body_bottom.getObj("scwin").setReturnValue("loop 를 빈 문자열로 설정 - 재생 시작 : " + scwin.fn_getPlayState("target2") + " , 재생 길이 경과 후 재생 종료(ended) : " + el2.ended);
        wf_body_bottom.getObj("scwin").setReturnValue("소스에서 loop 속성명 제거 시 해제 - 속성값 : " + JSON.stringify(el3.getAttribute("loop")) + " , 재생 길이 경과 후 재생 종료(ended) : " + el3.ended);

        [el1, el2, el3].forEach(function (el) { el.pause(); });
    }, 3500);
};



// 출력 HTML video 태그로 전달된 loop 속성값과 속성명 정의만으로의 설정 상태 확인
scwin.btn_getLoopAttr_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");

    wf_body_bottom.getObj("scwin").setReturnValue("출력 HTML video 태그의 loop 속성값 - target1 : " + JSON.stringify(el1.getAttribute("loop")) + " , target2 : " + JSON.stringify(el2.getAttribute("loop")) + " , target3 : " + JSON.stringify(el3.getAttribute("loop")));
    wf_body_bottom.getObj("scwin").setReturnValue("속성명 정의만으로 기능 설정 - 속성명만 정의한 target2 의 loop : " + el2.loop + " , 값을 명시한 target1 의 loop : " + el1.loop);
};
